func sha256Hex(b []byte) string {
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

// ---------------------------------------------------------------------------
// Golden loading (the established convention: dec.UseNumber, honest
// regeneration hints, no silent number coercion).
// ---------------------------------------------------------------------------

func goldenBytes(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_store.py): %v",
			name, err)
	}
	return data
}

func decodeGolden(t *testing.T, name string, into any) {
	t.Helper()
	dec := json.NewDecoder(bytes.NewReader(goldenBytes(t, name)))
	dec.UseNumber()
	if err := dec.Decode(into); err != nil {
		t.Fatalf("decode golden %s: %v", name, err)
	}
}

// pyNumber normalizes a decoded golden value so numbers compare against
// database/sql's driver-native values (int64 / string / nil). All numbers
// the fixture carries are integers; a future float fails LOUDLY here
// rather than comparing sloppily.
func pyNumber(v any) any {
	switch x := v.(type) {
	case json.Number:
		if i, err := x.Int64(); err == nil {
			return i
		}
		if f, err := x.Float64(); err == nil {
			return f
		}
		return x.String()
	case []any:
		out := make([]any, len(x))
		for i, e := range x {
			out[i] = pyNumber(e)
		}
		return out
	default:
		return v
	}
}

// ---------------------------------------------------------------------------
// 1. The timestamp grammar (ADR-0003 decision 4 — the naive/UTC helpers).
// ---------------------------------------------------------------------------

type fixedProbe struct {
	In            [8]any  `json:"in"` // y, mo, d, h, mi, s, us, tz_minutes|null
	ISOAuto       string  `json:"iso_auto"`
	ISOSeconds    string  `json:"iso_seconds"`
	ISOUTCSeconds *string `json:"iso_utc_seconds"`
}

func probeTime(t *testing.T, p fixedProbe) time.Time {
	t.Helper()
	in := p.In
	num := func(i int) int {
		n, ok := in[i].(json.Number)
		if !ok {
			t.Fatalf("probe %v: field %d is not a number", in, i)
		}
		v, err := n.Int64()
		if err != nil {
			t.Fatalf("probe %v: field %d: %v", in, i, err)
		}
		return int(v)
	}
	y, mo, d := num(0), num(1), num(2)
	h, mi, s, us := num(3), num(4), num(5), num(6)
	loc := time.UTC // naive datetimes: zone-independent wall digits
	if in[7] != nil {
		loc = time.FixedZone("", num(7)*60)
	}
	return time.Date(y, time.Month(mo), d, h, mi, s, us*1000, loc)
}

// TestTimestampGrammarGolden — every fixed probe from the generated
// corpus, byte-exact: PyISOFormat == isoformat() (the auto-timespec
// quirk: fraction IFF microsecond != 0, zero-padded to 6 digits),
// PyISOFormatSeconds == isoformat(timespec='seconds'), and for
// tz-carrying probes PyISOUTCSeconds == astimezone(utc).isoformat(
// timespec='seconds'). The naive helpers emit the WALL CLOCK of whatever
// zone t carries (no offset) — pinned via the tz rows' offset-stripped
// iso_seconds.
func TestTimestampGrammarGolden(t *testing.T) {
	var doc struct {
		Schema int          `json:"schema"`
		Fixed  []fixedProbe `json:"fixed"`
	}
	decodeGolden(t, "timestamp_grammar.golden.json", &doc)
	if len(doc.Fixed) == 0 {
		t.Fatal("empty fixed corpus")
	}
	for _, p := range doc.Fixed {
		tt := probeTime(t, p)
		// The naive helpers emit the wall clock WITHOUT offset; the golden's
		// tz rows carry an offset suffix — strip it for those rows.
		wantAuto, wantSecs := p.ISOAuto, p.ISOSeconds
		if p.In[7] != nil {
			wantAuto = stripOffset(p.ISOAuto)
			wantSecs = stripOffset(p.ISOSeconds)
		}
		if got := PyISOFormat(tt); got != wantAuto {
			t.Errorf("PyISOFormat(%v) = %q; want %q", p.In, got, wantAuto)
		}
		if got := PyISOFormatSeconds(tt); got != wantSecs {
			t.Errorf("PyISOFormatSeconds(%v) = %q; want %q", p.In, got, wantSecs)
		}
		if p.ISOUTCSeconds != nil {
			if got := PyISOUTCSeconds(tt); got != *p.ISOUTCSeconds {
				t.Errorf("PyISOUTCSeconds(%v) = %q; want %q", p.In, got, *p.ISOUTCSeconds)
			}
		}
	}
}

// stripOffset removes a trailing ±HH:MM from a tz-carrying golden string
// so the naive (offset-less) helpers can be pinned on tz rows too.
func stripOffset(s string) string {
	if len(s) >= 6 {
		tail := s[len(s)-6:]
		if (tail[0] == '+' || tail[0] == '-') &&
			tail[3] == ':' {
			return s[:len(s)-6]
		}
	}
	return s
}

// TestNowHelpersShapeAndLocalClock — the three Now shapes as the Go side
// produces them RIGHT NOW: the golden's regexes (generation-clock
// independent) + Local wall-clock self-consistency (the helpers format
// time.Now()'s own local wall clock, mirroring datetime.now()).
func TestNowHelpersShapeAndLocalClock(t *testing.T) {
	var doc struct {
		NowShapeRegexes struct {
			RegexNaiveAuto    string `json:"regex_naive_auto"`
			RegexNaiveSeconds string `json:"regex_naive_seconds"`
			RegexUTCSeconds   string `json:"regex_utc_seconds"`
		} `json:"now_shape_regexes"`
	}
	decodeGolden(t, "timestamp_grammar.golden.json", &doc)

	now := time.Now()
	auto := PyISOFormat(now)
	secs := PyISOFormatSeconds(now)
	utc := PyISOUTCSeconds(now)

	re, err := regexp.Compile(doc.NowShapeRegexes.RegexNaiveAuto)
	if err != nil {
		t.Fatalf("regex_naive_auto: %v", err)
	}
	if !re.MatchString(auto) {
		t.Errorf("PyISOFormat(time.Now()) = %q; does not match %q",
			auto, doc.NowShapeRegexes.RegexNaiveAuto)
	}
	re, err = regexp.Compile(doc.NowShapeRegexes.RegexNaiveSeconds)
	if err != nil {
		t.Fatalf("regex_naive_seconds: %v", err)
	}
	if !re.MatchString(secs) {
		t.Errorf("PyISOFormatSeconds(time.Now()) = %q; does not match %q",
			secs, doc.NowShapeRegexes.RegexNaiveSeconds)
	}
	re, err = regexp.Compile(doc.NowShapeRegexes.RegexUTCSeconds)
	if err != nil {
		t.Fatalf("regex_utc_seconds: %v", err)
	}
	if !re.MatchString(utc) {
		t.Errorf("PyISOUTCSeconds(time.Now()) = %q; does not match %q",
			utc, doc.NowShapeRegexes.RegexUTCSeconds)
	}

	// Local wall-clock consistency (mirrors datetime.now()'s localness):
	// the naive strings are exactly now's local wall digits, and the UTC
	// string is now's UTC wall digits.
	wantWall := now.Local().Format("2006-01-02T15:04:05")
	if auto[:19] != wantWall || secs != wantWall {
		t.Errorf("naive helpers disagree with Local wall clock: auto=%q secs=%q want=%q",
			auto, secs, wantWall)
	}
	if us := now.Nanosecond() / 1000; us != 0 {
		wantFrac := fmt.Sprintf(".%06d", us)
		if auto[19:] != wantFrac {
			t.Errorf("PyISOFormat fraction = %q; want %q", auto[19:], wantFrac)
		}
	}
	wantUTC := now.UTC().Format("2006-01-02T15:04:05") + "+00:00"
	if utc != wantUTC {
		t.Errorf("PyISOUTCSeconds = %q; want %q", utc, wantUTC)
	}
}

// ---------------------------------------------------------------------------
// 2. THE T-20 ACCEPTANCE — open the Python-created cache.db fixture.
// ---------------------------------------------------------------------------

type fixtureGolden struct {
	Schema               int    `json:"schema"`
	FixtureSha256        string `json:"fixture_sha256"`
	NoSidecarsAfterClose bool   `json:"no_sidecars_after_close"`
	PragmasThroughRef    struct {
		JournalMode string `json:"journal_mode"`
		BusyTimeout int64  `json:"busy_timeout"`
		Synchronous int64  `json:"synchronous"`
	} `json:"pragmas_through_reference"`
	Tables map[string]struct {
		Columns []string `json:"columns"`
		Rows    [][]any  `json:"rows"`
	} `json:"tables"`
}

type schemaGolden struct {
	Objects      [][]string         `json:"objects"` // type, name, tbl_name, sql
	TableColumns map[string][][]any `json:"table_columns"`
}

// timestampColumns returns the columns whose DECLARED type is one of
// DATE/DATETIME/TIMESTAMP — the set the modernc driver auto-converts to
// time.Time on read (see TestDriverDeclaredTimestampConversion). Reads
// of those columns must go through CAST(col AS TEXT) to keep Python's
// raw bytes (the CAST law, doc.go).
func timestampColumns(t *testing.T, sg schemaGolden, table string) map[string]bool {
	t.Helper()
	out := map[string]bool{}
	for _, col := range sg.TableColumns[table] {
		if len(col) < 2 {
			t.Fatalf("schema golden %s: bad column row %v", table, col)
		}
		name, _ := col[0].(string)
		typ, _ := col[1].(string)
		switch strings.ToUpper(typ) {
		case "DATE", "DATETIME", "TIMESTAMP", "TIME":
			out[name] = true
		}
	}
	return out
}

func loadFixtureGolden(t *testing.T) fixtureGolden {
	t.Helper()
	var g fixtureGolden
	decodeGolden(t, "cache_fixture_content.golden.json", &g)
	return g
}

// dumpTable reads every column of every row, driver-native values
// (int64 / string / nil), deterministically ordered — the same shape the
// golden's read-only introspection produced on the Python side.
// TIMESTAMP-declared columns are selected through CAST(col AS TEXT):
// the modernc driver otherwise parses them into time.Time (a mattn-
// compatible declared-type heuristic Python's sqlite3 never had),
// mangling the exact bytes. See TestDriverDeclaredTimestampConversion —
// the characterized driver behavior and the reason the CAST law exists.
func dumpTable(t *testing.T, db *sql.DB, table, orderBy string, tsCols map[string]bool) ([]string, [][]any) {
	t.Helper()
	rows, err := db.Query("SELECT * FROM " + table + " LIMIT 0")
	if err != nil {
		t.Fatalf("select %s: %v", table, err)
	}
	cols, err := rows.Columns()
	rows.Close()
	if err != nil {
		t.Fatalf("columns %s: %v", table, err)
	}
	selects := make([]string, len(cols))
	for i, c := range cols {
		if tsCols[c] {
			selects[i] = "CAST(" + c + " AS TEXT) AS " + c
		} else {
			selects[i] = c
		}
	}
	rows, err = db.Query("SELECT " + strings.Join(selects, ", ") +
		" FROM " + table + " ORDER BY " + orderBy)
	if err != nil {
		t.Fatalf("select %s: %v", table, err)
	}
	defer rows.Close()
	var out [][]any
	for rows.Next() {
		vals := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			t.Fatalf("scan %s: %v", table, err)
		}
		out = append(out, vals)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("iterate %s: %v", table, err)
	}
	return cols, out
}

func normalizeRows(rows [][]any) [][]any {
	out := make([][]any, len(rows))
	for i, r := range rows {
		out[i] = pyNumber(r).([]any)
	}
	return out
}

// TestOpenPythonCreatedFixture — THE acceptance: the Go store opens a
// real Python-created cache.db (built by the reference's own CacheDB
// methods), adopts its schema and rows byte-exactly, keeps WAL mode, and
// its own writes survive close+reopen. Python wrote with microseconds
// (processed_at / failed_at / decommissioned_at) and seconds
// (settled_at) — the golden pins those exact strings; Go reads them
// unchanged.
func TestOpenPythonCreatedFixture(t *testing.T) {
	g := loadFixtureGolden(t)
	var sg schemaGolden
	decodeGolden(t, "cache_schema.golden.json", &sg)
	src := filepath.Join("testdata", "cache_python_created.db")

	// The atomic-pair tie: the committed fixture is exactly the file the
	// content golden describes.
	data, err := os.ReadFile(src)
	if err != nil {
		t.Fatal(err)
	}
	if got := sha256Hex(data); got != g.FixtureSha256 {
		t.Fatalf("fixture sha256 = %s; golden records %s "+
			"(regenerate BOTH with testdiff/goldens/dump_store.py)",
			got, g.FixtureSha256)
	}

	// Never mutate testdata: work on a copy.
	work := filepath.Join(t.TempDir(), "cache_python_created.db")
	if err := os.WriteFile(work, data, 0o644); err != nil {
		t.Fatal(err)
	}

	db, err := Open(work)
	if err != nil {
		t.Fatalf("open Python-created fixture: %v", err)
	}
	defer db.Close()

	// The locking law's observable facts, as the Go open sets them —
	// matching what the reference's own open sets (golden's
	// pragmas_through_reference: wal / 30000 / 1).
	var mode string
	var busy, sync int64
	if err := db.SQL().QueryRow("PRAGMA journal_mode").Scan(&mode); err != nil {
		t.Fatalf("pragma journal_mode: %v", err)
	}
	if err := db.SQL().QueryRow("PRAGMA busy_timeout").Scan(&busy); err != nil {
		t.Fatalf("pragma busy_timeout: %v", err)
	}
	if err := db.SQL().QueryRow("PRAGMA synchronous").Scan(&sync); err != nil {
		t.Fatalf("pragma synchronous: %v", err)
	}
	if mode != "wal" {
		t.Errorf("journal_mode = %q; want %q (WAL asserted — the T-20 acceptance)", mode, "wal")
	}
	if busy != 30000 {
		t.Errorf("busy_timeout = %d; want 30000", busy)
	}
	if sync != 1 {
		t.Errorf("synchronous = %d; want 1 (NORMAL)", sync)
	}
	if mode != g.PragmasThroughRef.JournalMode || busy != g.PragmasThroughRef.BusyTimeout ||
		sync != g.PragmasThroughRef.Synchronous {
		t.Errorf("Go pragmas (%q/%d/%d) != reference's own (%q/%d/%d)",
			mode, busy, sync, g.PragmasThroughRef.JournalMode,
			g.PragmasThroughRef.BusyTimeout, g.PragmasThroughRef.Synchronous)
	}

	// Every table, byte-exact (columns + rows, driver-native values vs
	// normalized golden values).
	tableOrder := map[string]string{
		"processed_repos":      "repo_id",
		"checkpoints":          "id",
		"failed_repos":         "id",
		"decommissioned_repos": "url",
		"repos_settled":        "url",
		"cache_meta":           "key",
	}
	if len(g.Tables) != len(tableOrder) {
		t.Fatalf("golden tables = %d; test knows %d — regenerate goldens",
			len(g.Tables), len(tableOrder))
	}
	for table, orderBy := range tableOrder {
		want := g.Tables[table]
		tsCols := timestampColumns(t, sg, table)
		cols, rows := dumpTable(t, db.SQL(), table, orderBy, tsCols)
		if !reflect.DeepEqual(cols, want.Columns) {
			t.Errorf("%s columns = %v; want %v", table, cols, want.Columns)
		}
		got := normalizeRows(rows)
		if !reflect.DeepEqual(got, normalizeRows(want.Rows)) {
			t.Errorf("%s rows mismatch:\n got: %#v\nwant: %#v", table, got, want.Rows)
		}
	}

	// Write probes through the Go store — raw SQL here (the repos-ledger
	// API is T-24); the timestamps use the package's own Python-shape
	// helpers (eating the dogfood).
	nowAuto := PyISOFormat(time.Now())
	if _, err := db.SQL().Exec(
		"INSERT INTO cache_meta (key, value) VALUES (?, ?)",
		"go_write_probe", "written-by-go"); err != nil {
		t.Fatalf("go write cache_meta: %v", err)
	}
	if _, err := db.SQL().Exec(
		"INSERT INTO processed_repos "+
			"(repo_id, url, owner, repo_name, processed_at, last_checked, note_path, category) "+
			"VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
		333, "https://github.com/go/written", "go", "written",
		nowAuto, nowAuto, "Go/written.md", "Agents"); err != nil {
		t.Fatalf("go write processed_repos: %v", err)
	}

	// WAL is live: the sidecar exists while the writer is open.
	if _, err := os.Stat(work + "-wal"); err != nil {
		t.Errorf("-wal sidecar missing after Go write (WAL not live): %v", err)
	}

	// Durability: close, reopen, the Go-written rows are still there and
	// the Python-written ones unchanged.
	if err := db.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	db2, err := Open(work)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer db2.Close()
	var v string
	if err := db2.SQL().QueryRow(
		"SELECT value FROM cache_meta WHERE key = 'go_write_probe'").Scan(&v); err != nil {
		t.Fatalf("read back go_write_probe: %v", err)
	}
	if v != "written-by-go" {
		t.Errorf("go_write_probe = %q; want %q", v, "written-by-go")
	}
	var ts string
	if err := db2.SQL().QueryRow(
		"SELECT CAST(processed_at AS TEXT) FROM processed_repos WHERE repo_id = 333").Scan(&ts); err != nil {
		t.Fatalf("read back go timestamp: %v", err)
	}
	if ts != nowAuto {
		t.Errorf("go-written processed_at = %q; want %q (the naive helper shape, unchanged through the DB)", ts, nowAuto)
	}
	_, rows := dumpTable(t, db2.SQL(), "processed_repos", "repo_id",
		timestampColumns(t, sg, "processed_repos"))
	if len(rows) != len(g.Tables["processed_repos"].Rows)+1 {
		t.Errorf("processed_repos after Go write = %d rows; want %d",
			len(rows), len(g.Tables["processed_repos"].Rows)+1)
	}
}

// TestDriverDeclaredTimestampConversion — CHARACTERIZES the modernc
// driver's declared-type behavior (v1.36.1, the pinned version): a TEXT
// value from a DATE/DATETIME/TIMESTAMP-declared column is delivered as
// time.Time (parsed via the mattn-compatible format list — including
// re-serializing through database/sql into a DIFFERENT string shape,
// e.g. "+00:00"→"Z", trailing fraction zeros dropped), while the same
// value selected through CAST(col AS TEXT) — an expression with an empty
// declared type — comes back as the RAW bytes, exactly like Python's
// sqlite3 (which has no declared-type conversion at all). This is why
// the port's read law is: every query selecting a timestamp-declared
// column wraps it in CAST(... AS TEXT) (doc.go; ADR-0003 Am.1).
func TestDriverDeclaredTimestampConversion(t *testing.T) {
	db, err := Open(filepath.Join(t.TempDir(), "driverchar.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.SQL().Exec(
		"CREATE TABLE t (ts TIMESTAMP, n INTEGER)"); err != nil {
		t.Fatal(err)
	}
	const written = "2026-10-15T21:18:47.831145"
	if _, err := db.SQL().Exec(
		"INSERT INTO t VALUES (?, 111)", written); err != nil {
		t.Fatal(err)
	}

	// Raw select: the driver parses the declared-TIMESTAMP text into
	// time.Time — a value Python's sqlite3 would hand back as str.
	var raw any
	if err := db.SQL().QueryRow("SELECT ts FROM t").Scan(&raw); err != nil {
		t.Fatal(err)
	}
	if _, ok := raw.(time.Time); !ok {
		t.Fatalf("declared-TIMESTAMP select returned %T; the pinned "+
			"driver changed behavior — re-pin this law (ADR-0003 Am.1)", raw)
	}

	// CAST select: raw bytes, byte-identical to what was written.
	var cast any
	if err := db.SQL().QueryRow(
		"SELECT CAST(ts AS TEXT) FROM t").Scan(&cast); err != nil {
		t.Fatal(err)
	}
	s, ok := cast.(string)
	if !ok || s != written {
		t.Fatalf("CAST(ts AS TEXT) = %#v; want %q", cast, written)
	}

	// CAST is for TIMESTAMP columns ONLY: on an INTEGER column it
	// stringifies the value (111 → "111") — the port casts exactly
	// the timestamp-declared columns, nothing else.
	var castInt any
	if err := db.SQL().QueryRow(
		"SELECT CAST(n AS TEXT) FROM t").Scan(&castInt); err != nil {
		t.Fatal(err)
	}
	if s, ok := castInt.(string); !ok || s != "111" {
		t.Fatalf("CAST(n AS TEXT) = %#v; want string \"111\" (why CAST stays scoped)", castInt)
	}
	var rawInt any
	if err := db.SQL().QueryRow("SELECT n FROM t").Scan(&rawInt); err != nil {
		t.Fatal(err)
	}
	if n, ok := rawInt.(int64); !ok || n != 111 {
		t.Fatalf("raw INTEGER = %#v; want int64 111", rawInt)
	}
}

// TestOpenCreatesFreshFile — the fresh-install shape: a path that does
// not exist is created (Python's sqlite3.connect semantics), the unified
// pragmas apply (WAL — the deliberate unification over Python's
// CacheDB-only WAL, documented in doc.go), and the file is a usable
// database.
func TestOpenCreatesFreshFile(t *testing.T) {
	path := filepath.Join(t.TempDir(), "fresh", "nested", "cache.db")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	db, err := Open(path)
	if err != nil {
		t.Fatalf("open fresh path: %v", err)
	}
	defer db.Close()
	if _, err := os.Stat(path); err != nil {
		t.Fatalf("fresh db file not created: %v", err)
	}
	var mode string
	if err := db.SQL().QueryRow("PRAGMA journal_mode").Scan(&mode); err != nil {
		t.Fatal(err)
	}
	if mode != "wal" {
		t.Errorf("fresh db journal_mode = %q; want wal", mode)
	}
	if _, err := db.SQL().Exec("CREATE TABLE probe (k TEXT)"); err != nil {
		t.Fatalf("create on fresh db: %v", err)
	}
	if _, err := db.SQL().Exec("INSERT INTO probe VALUES ('x')"); err != nil {
		t.Fatalf("insert on fresh db: %v", err)
	}
	var k string
	if err := db.SQL().QueryRow("SELECT k FROM probe").Scan(&k); err != nil {
		t.Fatalf("select on fresh db: %v", err)
	}
	if k != "x" {
		t.Errorf("probe k = %q; want x", k)
	}
}

// ---------------------------------------------------------------------------
// 3. The sqlite-level shadow-cache assertions — DEFERRED FROM T-12,
//    recorded in SESSION-004, landing HERE (modernc in hand).
//    Port of tests/test_phase0.py
//    test_shadow_cache_reads_real_state_writes_are_discarded.
// ---------------------------------------------------------------------------

func TestShadowCacheReadsRealStateWritesAreDiscarded(t *testing.T) {
	dryrun.Disable()
	dryrun.Clear()
	defer func() {
		dryrun.Disable()
		dryrun.Clear()
	}()

	tmp := t.TempDir()
	real := filepath.Join(tmp, "cache.db")

	// The real cache with real state — through a REAL SQLite handle (the
	// sqlite-level point; Python's test used raw sqlite3 the same way).
	rdb, err := Open(real)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := rdb.SQL().Exec("CREATE TABLE t (k TEXT)"); err != nil {
		t.Fatal(err)
	}
	if _, err := rdb.SQL().Exec("INSERT INTO t VALUES ('real-state')"); err != nil {
		t.Fatal(err)
	}
	if err := rdb.Close(); err != nil {
		t.Fatal(err)
	}

	dryrun.Enable()
	shadow := dryrun.ShadowCachePath(real)
	if shadow == real {
		t.Fatalf("shadow path == real path (%s)", shadow)
	}
	// the shadow sees the real rows…
	sdb, err := Open(shadow)
	if err != nil {
		t.Fatalf("open shadow with a real SQLite handle: %v", err)
	}
	var k string
	if err := sdb.SQL().QueryRow("SELECT k FROM t").Scan(&k); err != nil {
		t.Fatalf("shadow read: %v", err)
	}
	if k != "real-state" {
		t.Fatalf("shadow sees %q; want real-state", k)
	}
	// …but writes land only in the shadow
	if _, err := sdb.SQL().Exec("INSERT INTO t VALUES ('dry-run-state')"); err != nil {
		t.Fatal(err)
	}
	if err := sdb.Close(); err != nil {
		t.Fatal(err)
	}
	rdb2, err := Open(real)
	if err != nil {
		t.Fatal(err)
	}
	var n int64
	if err := rdb2.SQL().QueryRow("SELECT COUNT(*) FROM t").Scan(&n); err != nil {
		t.Fatal(err)
	}
	if n != 1 {
		t.Fatalf("real cache after shadow write: %d rows; want 1", n)
	}
	if err := rdb2.Close(); err != nil {
		t.Fatal(err)
	}

	dryrun.Disable()
	// after disable, the real cache is still untouched
	rdb3, err := Open(real)
	if err != nil {
		t.Fatal(err)
	}
	defer rdb3.Close()
	if err := rdb3.SQL().QueryRow("SELECT COUNT(*) FROM t").Scan(&n); err != nil {
		t.Fatal(err)
	}
	if n != 1 {
		t.Fatalf("real cache after disable: %d rows; want 1", n)
	}
}

// ---------------------------------------------------------------------------
// 4. THE SQLITE LAW — concurrency across handles on one file.
//    Port of tests/test_syncreview.py TestLedgerConcurrency.
//    test_two_threads_mark_the_same_db (the DeferredLog rig there; here
//    the shared store plumbing itself): N goroutines, each with its OWN
//    handle, write concurrently — busy_timeout + WAL give a clean wait,
//    never an error, and every row lands.
// ---------------------------------------------------------------------------

func TestConcurrentHandlesSameFile(t *testing.T) {
	path := filepath.Join(t.TempDir(), "shared.db")
	init, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := init.SQL().Exec("CREATE TABLE marks (n INTEGER, i INTEGER)"); err != nil {
		t.Fatal(err)
	}
	if err := init.Close(); err != nil {
		t.Fatal(err)
	}

	const workers = 4
	const perWorker = 20
	var wg sync.WaitGroup
	errs := make(chan error, workers)
	for n := 0; n < workers; n++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			db, err := Open(path)
			if err != nil {
				errs <- fmt.Errorf("worker %d open: %w", n, err)
				return
			}
			defer db.Close()
			for i := 0; i < perWorker; i++ {
				if _, err := db.SQL().Exec(
					"INSERT INTO marks VALUES (?, ?)", n, i); err != nil {
					errs <- fmt.Errorf("worker %d insert %d: %w", n, i, err)
					return
				}
			}
		}(n)
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Error(err)
	}

	final, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer final.Close()
	var count int64
	if err := final.SQL().QueryRow("SELECT COUNT(*) FROM marks").Scan(&count); err != nil {
		t.Fatal(err)
	}
	if count != workers*perWorker {
		t.Errorf("marks = %d; want %d (a clean wait, every row landed)", count, workers*perWorker)
	}
}

// TestCloseIdempotent — port of test_close_is_idempotent (the same law
// CacheDB.close documents: "close() is idempotent; call sites use
// try/finally").
func TestCloseIdempotent(t *testing.T) {
	db, err := Open(filepath.Join(t.TempDir(), "cache.db"))
	if err != nil {
		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatalf("first close: %v", err)
	}
	if err := db.Close(); err != nil {
		t.Fatalf("second close must be a no-op; got %v", err)
	}
}

// ---------------------------------------------------------------------------
// 5. The port's own contract — the DSN shape (the locking law's
//    test_locking_law_in_source realized as behavior).
// ---------------------------------------------------------------------------

func TestDSNShape(t *testing.T) {
	got := DSN("/vault/app/cache.db")
	want := "/vault/app/cache.db" +
		"?_pragma=busy_timeout(30000)" +
		"&_pragma=journal_mode(WAL)" +
		"&_pragma=synchronous(NORMAL)"
	if got != want {
		t.Errorf("DSN = %q; want %q", got, want)
	}
}
